/**
 * Banded Needleman-Wunsch alignment with affine gap penalties.
 *
 * Designed for DNA sequence comparison where:
 * - Sequences are mostly identical (small edit distance)
 * - Contiguous gaps should be preferred over scattered gaps
 * - Performance matters for sequences up to 70kb+
 *
 * Affine gap model: opening a new gap costs more than extending one.
 * This ensures deletions/insertions are placed as single contiguous gaps
 * rather than being split across repetitive regions.
 *
 * Banding: only computes within ±bandwidth of the main diagonal,
 * making it O(n * bandwidth) instead of O(n * m).
 */

export interface GappedAlignment {
  oldGapped: string;
  newGapped: string;
}

// Scoring parameters tuned for DNA diff (not homology search).
// High match reward + heavy mismatch penalty ensures the aligner prefers
// gaps over mismatches when sequences genuinely differ (editing operations
// are insertions/deletions, not substitutions in most cases).
// Affine gap model: opening a gap is expensive, extending is cheap —
// this keeps contiguous edits as single gap runs.
const MATCH = 2;
const MISMATCH = -6; // Very heavy: always prefer gap over mismatch for DNA diff
const GAP_OPEN = -5; // Expensive to start a new gap
const GAP_EXTEND = -0.1; // Very cheap to extend — strongly prefer contiguous gaps

// Default bandwidth for banded alignment. Sequences differing by <5%
// are well-captured within this band.
const DEFAULT_BANDWIDTH = 200;

const GAP_CHAR = '-';
const NEG_INF = -1e9;

/**
 * Align two sequences using banded Needleman-Wunsch with affine gap penalties.
 *
 * Returns gapped alignment strings where:
 * - Gaps in oldGapped = insertions in new
 * - Gaps in newGapped = deletions from old
 * - Different chars at same column = substitutions
 * - Same chars at same column = matches
 *
 * The affine gap model ensures contiguous deletions/insertions are represented
 * as single gap runs, even on low-alphabet sequences (DNA).
 */
export function alignSequences(
  oldSeq: string,
  newSeq: string,
  bandwidth?: number
): GappedAlignment {
  const n = oldSeq.length;
  const m = newSeq.length;

  // Edge cases
  if (n === 0 && m === 0) return { oldGapped: '', newGapped: '' };
  if (n === 0) return { oldGapped: GAP_CHAR.repeat(m), newGapped: newSeq };
  if (m === 0) return { oldGapped: oldSeq, newGapped: GAP_CHAR.repeat(n) };
  if (oldSeq === newSeq) return { oldGapped: oldSeq, newGapped: newSeq };
  if (n === m && isSparseSameLengthSubstitution(oldSeq, newSeq)) {
    return { oldGapped: oldSeq, newGapped: newSeq };
  }

  // For very short sequences, use full matrix (no banding)
  const bw = bandwidth ?? Math.max(DEFAULT_BANDWIDTH, Math.abs(n - m) + 10);
  const useBanding = n > bw * 2 || m > bw * 2;

  if (useBanding) {
    return bandedAffineNW(oldSeq, newSeq, bw);
  }
  return fullAffineNW(oldSeq, newSeq);
}

function isSparseSameLengthSubstitution(oldSeq: string, newSeq: string): boolean {
  // Keep short same-length replacements on the full NW path; sequence-diff
  // intentionally decomposes some small replacements as delete+insert.
  if (oldSeq.length < 1024) return false;

  const limit = Math.max(8, Math.min(64, Math.floor(oldSeq.length * 0.001)));
  const maxRunLength = 8;
  let mismatches = 0;
  let runLength = 0;

  for (let i = 0; i < oldSeq.length; i++) {
    if (oldSeq[i] === newSeq[i]) {
      runLength = 0;
      continue;
    }

    mismatches++;
    runLength++;
    if (mismatches > limit || runLength > maxRunLength) return false;
  }

  return mismatches > 0;
}

/**
 * Full (unbanded) affine gap Needleman-Wunsch.
 * O(n*m) time and space. Used for short sequences.
 */
function fullAffineNW(oldSeq: string, newSeq: string): GappedAlignment {
  const n = oldSeq.length;
  const m = newSeq.length;

  // Three matrices:
  // M[i][j] = best score ending with old[i-1] aligned to new[j-1] (match/mismatch)
  // X[i][j] = best score ending with a gap in new (deletion from old)
  // Y[i][j] = best score ending with a gap in old (insertion in new)
  const M: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(NEG_INF));
  const X: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(NEG_INF));
  const Y: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(NEG_INF));

  // Traceback: 0=M, 1=X(gap in new), 2=Y(gap in old)
  // For each matrix, store which matrix the optimal came from
  const trM: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  const trX: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  const trY: number[][] = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));

  // Initialize
  M[0][0] = 0;
  for (let i = 1; i <= n; i++) {
    X[i][0] = GAP_OPEN + (i - 1) * GAP_EXTEND;
    trX[i][0] = 1; // came from X
  }
  for (let j = 1; j <= m; j++) {
    Y[0][j] = GAP_OPEN + (j - 1) * GAP_EXTEND;
    trY[0][j] = 2; // came from Y
  }

  // Fill
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      const score = oldSeq[i - 1] === newSeq[j - 1] ? MATCH : MISMATCH;

      // M[i][j]: align old[i-1] with new[j-1]
      const mFromM = M[i - 1][j - 1] + score;
      const mFromX = X[i - 1][j - 1] + score;
      const mFromY = Y[i - 1][j - 1] + score;
      if (mFromM >= mFromX && mFromM >= mFromY) {
        M[i][j] = mFromM;
        trM[i][j] = 0;
      } else if (mFromX >= mFromY) {
        M[i][j] = mFromX;
        trM[i][j] = 1;
      } else {
        M[i][j] = mFromY;
        trM[i][j] = 2;
      }

      // X[i][j]: gap in new (consume old[i-1], skip new)
      const xFromM = M[i - 1][j] + GAP_OPEN;
      const xFromX = X[i - 1][j] + GAP_EXTEND;
      if (xFromM >= xFromX) {
        X[i][j] = xFromM;
        trX[i][j] = 0;
      } else {
        X[i][j] = xFromX;
        trX[i][j] = 1;
      }

      // Y[i][j]: gap in old (skip old, consume new[j-1])
      const yFromM = M[i][j - 1] + GAP_OPEN;
      const yFromY = Y[i][j - 1] + GAP_EXTEND;
      if (yFromM >= yFromY) {
        Y[i][j] = yFromM;
        trY[i][j] = 0;
      } else {
        Y[i][j] = yFromY;
        trY[i][j] = 2;
      }
    }
  }

  // Traceback from best of M[n][m], X[n][m], Y[n][m]
  let state: number;
  const finalM = M[n][m];
  const finalX = X[n][m];
  const finalY = Y[n][m];
  if (finalM >= finalX && finalM >= finalY) {
    state = 0;
  } else if (finalX >= finalY) {
    state = 1;
  } else {
    state = 2;
  }

  return traceback(oldSeq, newSeq, state, trM, trX, trY, n, m);
}

/**
 * Banded affine gap Needleman-Wunsch.
 * O(n * bandwidth) time and space. Used for long sequences.
 */
function bandedAffineNW(oldSeq: string, newSeq: string, bw: number): GappedAlignment {
  const n = oldSeq.length;
  const m = newSeq.length;

  // For banded, we only compute cells within ±bw of the diagonal j = i * (m/n)
  // Use flat arrays indexed by (i, j-jMin) for memory efficiency
  const width = 2 * bw + 1;
  const jMinByRow = new Int32Array(n + 1);
  const jMaxByRow = new Int32Array(n + 1);
  const rowOffsetByRow = new Int32Array(n + 1);
  for (let i = 0; i <= n; i++) {
    const center = Math.round((i * m) / n);
    const min = Math.max(0, center - bw);
    jMinByRow[i] = min;
    jMaxByRow[i] = Math.min(m, center + bw);
    rowOffsetByRow[i] = i * width - min;
  }

  const M = new Float64Array((n + 1) * width).fill(NEG_INF);
  const X = new Float64Array((n + 1) * width).fill(NEG_INF);
  const Y = new Float64Array((n + 1) * width).fill(NEG_INF);
  const trM = new Uint8Array((n + 1) * width);
  const trX = new Uint8Array((n + 1) * width);
  const trY = new Uint8Array((n + 1) * width);

  const idx = (i: number, j: number) => rowOffsetByRow[i] + j;

  // Initialize
  M[idx(0, 0)] = 0;
  for (let i = 1; i <= n && i <= bw; i++) {
    const j = 0;
    if (j >= jMinByRow[i] && j <= jMaxByRow[i]) {
      X[idx(i, j)] = GAP_OPEN + (i - 1) * GAP_EXTEND;
      trX[idx(i, j)] = 1;
    }
  }
  for (let j = 1; j <= m && j <= bw; j++) {
    const i = 0;
    if (j >= jMinByRow[i] && j <= jMaxByRow[i]) {
      Y[idx(i, j)] = GAP_OPEN + (j - 1) * GAP_EXTEND;
      trY[idx(i, j)] = 2;
    }
  }

  // Fill
  for (let i = 1; i <= n; i++) {
    const rowOffset = rowOffsetByRow[i];
    const prevRowOffset = rowOffsetByRow[i - 1];
    const minI = jMinByRow[i];
    const maxI = jMaxByRow[i];
    const prevMin = jMinByRow[i - 1];
    const prevMax = jMaxByRow[i - 1];
    const lo = Math.max(1, minI);
    const hi = maxI;
    for (let j = lo; j <= hi; j++) {
      const score = oldSeq[i - 1] === newSeq[j - 1] ? MATCH : MISMATCH;
      const k = rowOffset + j;

      // M[i][j]
      if (j - 1 >= prevMin && j - 1 <= prevMax) {
        const prev = prevRowOffset + j - 1;
        const mFromM = M[prev] + score;
        const mFromX = X[prev] + score;
        const mFromY = Y[prev] + score;
        if (mFromM >= mFromX && mFromM >= mFromY) {
          M[k] = mFromM;
          trM[k] = 0;
        } else if (mFromX >= mFromY) {
          M[k] = mFromX;
          trM[k] = 1;
        } else {
          M[k] = mFromY;
          trM[k] = 2;
        }
      }

      // X[i][j]
      if (j >= prevMin && j <= prevMax) {
        const prev = prevRowOffset + j;
        const xFromM = M[prev] + GAP_OPEN;
        const xFromX = X[prev] + GAP_EXTEND;
        if (xFromM >= xFromX) {
          X[k] = xFromM;
          trX[k] = 0;
        } else {
          X[k] = xFromX;
          trX[k] = 1;
        }
      }

      // Y[i][j]
      if (j - 1 >= minI && j - 1 <= maxI) {
        const prev = rowOffset + j - 1;
        const yFromM = M[prev] + GAP_OPEN;
        const yFromY = Y[prev] + GAP_EXTEND;
        if (yFromM >= yFromY) {
          Y[k] = yFromM;
          trY[k] = 0;
        } else {
          Y[k] = yFromY;
          trY[k] = 2;
        }
      }
    }
  }

  // Traceback
  const k = idx(n, m);
  const finalM = M[k];
  const finalX = X[k];
  const finalY = Y[k];
  let state: number;
  if (finalM >= finalX && finalM >= finalY) {
    state = 0;
  } else if (finalX >= finalY) {
    state = 1;
  } else {
    state = 2;
  }

  // For banded traceback, we need full traceback matrices — reconstruct from flat arrays
  // Build sparse traceback arrays for the path
  const oldChars: string[] = [];
  const newChars: string[] = [];
  let i = n;
  let j = m;

  while (i > 0 || j > 0) {
    if (j < jMinByRow[i] || j > jMaxByRow[i]) {
      // Out of band — shouldn't happen with proper bandwidth
      // Force gap in the shorter dimension
      if (i > 0) {
        oldChars.push(oldSeq[i - 1]);
        newChars.push(GAP_CHAR);
        i--;
      } else {
        oldChars.push(GAP_CHAR);
        newChars.push(newSeq[j - 1]);
        j--;
      }
      continue;
    }

    const k = idx(i, j);
    if (state === 0) {
      // Match/mismatch — consume both
      oldChars.push(oldSeq[i - 1]);
      newChars.push(newSeq[j - 1]);
      state = trM[k];
      i--;
      j--;
    } else if (state === 1) {
      // Gap in new (deletion from old)
      oldChars.push(oldSeq[i - 1]);
      newChars.push(GAP_CHAR);
      state = trX[k];
      i--;
    } else {
      // Gap in old (insertion in new)
      oldChars.push(GAP_CHAR);
      newChars.push(newSeq[j - 1]);
      state = trY[k];
      j--;
    }
  }

  oldChars.reverse();
  newChars.reverse();

  return {
    oldGapped: oldChars.join(''),
    newGapped: newChars.join(''),
  };
}

/**
 * Traceback for the full (unbanded) alignment.
 */
function traceback(
  oldSeq: string,
  newSeq: string,
  startState: number,
  trM: number[][],
  trX: number[][],
  trY: number[][],
  n: number,
  m: number
): GappedAlignment {
  const oldChars: string[] = [];
  const newChars: string[] = [];
  let i = n;
  let j = m;
  let state = startState;

  while (i > 0 || j > 0) {
    if (state === 0) {
      if (i === 0 || j === 0) {
        // Edge: consume remaining
        if (i > 0) {
          oldChars.push(oldSeq[i - 1]);
          newChars.push(GAP_CHAR);
          i--;
        } else {
          oldChars.push(GAP_CHAR);
          newChars.push(newSeq[j - 1]);
          j--;
        }
      } else {
        oldChars.push(oldSeq[i - 1]);
        newChars.push(newSeq[j - 1]);
        state = trM[i][j];
        i--;
        j--;
      }
    } else if (state === 1) {
      if (i === 0) {
        oldChars.push(GAP_CHAR);
        newChars.push(newSeq[j - 1]);
        j--;
      } else {
        oldChars.push(oldSeq[i - 1]);
        newChars.push(GAP_CHAR);
        state = trX[i][j];
        i--;
      }
    } else {
      if (j === 0) {
        oldChars.push(oldSeq[i - 1]);
        newChars.push(GAP_CHAR);
        i--;
      } else {
        oldChars.push(GAP_CHAR);
        newChars.push(newSeq[j - 1]);
        state = trY[i][j];
        j--;
      }
    }
  }

  oldChars.reverse();
  newChars.reverse();

  return {
    oldGapped: oldChars.join(''),
    newGapped: newChars.join(''),
  };
}
